          "<b>顺序存储结构</b>：采用一组连续的存储单元存放所有数据元素，两个逻辑上相邻的元素在存储器中的存储位置也相邻，将逻辑结构直接映射到存储结构。优点：存储效率高，元素之间的关系没有占用额外空间；可实现随机存取，由逻辑序号直接计算出对应元素的存储地址。缺点：不便于数据修改，对元素的插入或删除操作可能需要移动一系列元素。",
          "<b>链式存储结构</b>：每个逻辑元素用一个单独分配的内存结点存储，结点地址不一定连续，无须占用一整块存储空间；给每个结点附加指针域，用于存放相邻结点的存储地址。优点：便于数据修改，插入或删除时仅需修改相应结点的指针域、不必移动结点。缺点：存储空间利用率较低（指针域占用额外空间），且不能对元素进行随机存取。",
          "<b>索引存储结构</b>：在存储数据元素信息的同时还建立附加的索引表；存储所有元素信息的表称为主数据表，索引项的一般形式为“关键字，地址”，索引表中所有索引项通常按关键字有序排列。优点：查找效率高。缺点：需要建立索引表，增加空间开销。",
