          "采用链式存储结构——head链表：需要遍历该链表，用i记录查找结点的逻辑序号、p指向首结点（i=1）；由于i≠2，执行p=p→next移到一个结点，同时i增1变为2；此时i=2，p指向的结点就是要找的结点，返回p→name，即“刘丽”。"
