          "静态存储空间分配方式：在程序编译期间分配固定的存储空间（如int a[10]），在变量定义时就分配存储单元并一直保持不变，直至整个程序结束；它属于自动变量，超出作用范围时系统自动释放其内存空间。",
          "动态存储空间分配方式：在程序运行期间根据需要动态地分配存储空间，例如malloc()/free()函数对——用malloc()为一个指针变量分配一片连续的空间，不再需要时用free()释放p所指向的空间；优点是可以根据程序需要扩大或缩小分配的空间（链式存储结构常用这种方式）。"
