          "ADT有两个重要特征：<b>数据抽象</b>——用ADT描述程序处理的数据特征、其能完成的功能以及它和外部用户的接口（即外界使用它的方法）；<b>数据封装</b>——将程序的外部特性和其内部实现细节分离，并且对外部用户隐藏其内部实现细节。",
