       "solution": "第1步，确定数据元素集合D：城市表中共有5个元素，每个元素用唯一标识它的区号表示，即D={010,021,027,029,025}。\n第2步，确定关系集合R：按表中元素的排列顺序，相邻元素之间构成序偶关系，即010与021相邻、021与027相邻、027与029相邻、029与025相邻，只有一种关系r。\n第3步，写出二元组表示：\nCity=(D,R)\nD={010,021,027,029,025}\nR={r}\nr={<010,021>,<021,027>,<027,029>,<029,025>}",
