       "solution": "第1步，画出图形表示（原书图1.4）：每个序偶<x,y>画成从x指向y的带箭头连线。a引出三条边指向b、c、d；b引出一条边指向e；c引出两条边指向f、g；d引出三条边指向h、i、j。e、f、g、h、i、j为树叶结点。\n第2步，分析前驱与后继：除树根结点a以外，每个结点有且仅有一个前驱结点；但每个结点可有多个后继结点（树叶结点可视作具有零个后继结点）。\n第3步，得出结论：B₁是一种树形结构。",
