       "solution": "第1步，画出图形表示（原书图1.5）：7个结点48、25、64、57、82、36、75上画出两种关系，r₁对应图中的虚线部分，r₂对应图中的实线部分。\n第2步，分析r₁：<25,36>,<36,48>,<48,57>,<57,64>,<64,75>,<75,82>把7个元素按36、48、57、64、75、82的次序依次连成一条链（25→36→48→57→64→75→82），除首尾外每个元素有且仅有一个前驱和一个后继，故r₁为线性结构。\n第3步，分析r₂：以48为根，48的孩子为25和64；25的孩子为36；64的孩子为57和82；82的孩子为75。除根结点48外每个结点有且仅有一个前驱，但可有多个后继，故r₂为树形结构。\n第4步，得出结论：r₁为线性结构、r₂为树形结构，因此在同一数据集合上可以有多种逻辑关系。",
