          "输出型参数不能只按输入型参数设计：如交换两个整数的函数swap1(int x,int y)，在该函数中确实实现了两个形参x和y的值交换，但调用swap1(a,b)时a和b实参值并不会发生交换，因为这里的形参x、y既是输入型参数又是输出型参数，而swap1(x,y)中仅将其作为输入型参数设计。",
          "改正方法1（指针方式回传形参的值）：改为swap2(int *x,int *y)，调用方式改为swap2(&a,&b)，其中&a、&b分别是实参a、b的地址；但改正后的算法比较复杂，可读性差。",
          "改正方法2（引用型形参）：C++提供引用运算符“&”，建立引用后引用变量作为目标变量的别名，对引用变量的改动实际上是对目标变量的改动；当采用引用型形参时，调用函数会将形参的改变回传给实参。本书后面均采用这种方式设计算法。"
