         "k": "text",
         "p": "本教材（李春葆《数据结构教程（第6版）》第2章，P29-70）未专述静态链表：本章介绍的线性表存储结构为顺序表（2.2节）与链表（2.3节：单链表、双链表、循环链表），未安排静态链表小节。静态链表的基本思想是用数组元素模拟结点、以数组下标充当\"指针\"来链接结点，从而在不使用指针类型的场合实现链式结构；此结论为该知识点的通行定义，本学习数据如实注明教材未专述，不引入书外代码与例题展开。"
