         "k": "text",
         "p": "DFS从初始点出发以纵向方式逐步向前访问顶点，找不到相邻未访问顶点就回退，这种思路常用于图查找算法。教材给出5类应用：判断是否连通（例8.3）、判断u到v是否存在简单路径（例8.4 ExistPath）、输出u到v的一条简单路径（例8.5 FindaPath）、输出u到v的所有简单路径（例8.6 FindAllPath，带回溯）、输出长度为l的所有简单路径（例8.7 PathlenAll）以及求经过某顶点k的所有简单回路（例8.8 DFSPath）。"
