       "no": "例8.3",
       "stem": "假设图G采用邻接表存储，设计一个算法，判断无向图G是否为连通图。若是连通图，返回true，否则返回false。",
       "solution": "第1步：算法思路。可采用某种遍历方式判断：先给visited数组（全局变量）所有元素置初值0，然后从顶点0开始遍历该图。\n第2步：一次遍历之后检查所有顶点，若每个顶点i的visited[i]均为1，说明从0能到达所有顶点，该图是连通图；若存在顶点visited[i]为0，则该图是非连通图。\n第3步：实现函数bool Connect(AdjGraph *G)：flag初值true；for循环把visited全部置0；调用DFS(G,0)从顶点0深度优先遍历；再for循环检查每个顶点，若visited[i]==0则置flag=false并break；最后返回flag。",
       "src": "教材P264"
