       "stem": "假设图G采用邻接表存储，设计一个算法输出图G中从顶点u到顶点v的一条简单路径（假设图G中从顶点u到顶点v至少有一条简单路径）。",
       "solution": "第1步：采用深度优先遍历。在DFS基础上增加v、path和d几个形参：path存放顶点u到顶点v的路径，d表示path中的路径长度，初值为−1（原书图8.15）。\n第2步：访问顶点u时d++、把u存入path[d]、置visited[u]=1。\n第3步：若u==v，说明已遍历到顶点v，输出path[0..d]并返回（原书图8.16）。\n第4步：若u不是v，则p沿u的边表移动，对每个未访问邻接点w递归调用FindaPath(G,w,v,path,d)。函数FindaPath即上述过程。",
