       "stem": "假设图G采用邻接表存储，设计一个算法输出图G中从顶点u到顶点v的所有简单路径（假设图G中从顶点u到顶点v至少有一条简单路径）。",
       "solution": "第1步：利用带回溯的深度优先遍历。由于遍历中每个顶点只访问一次，所以每条路径必定是简单路径。形参path存放路径、d表示路径长度（初值−1）。\n第2步：从u出发遍历时先置visited[u]=1、d++并把u加到path中。\n第3步：若满足u==v，表示找到一条简单路径，输出path[0..d]；再从终点v回退（置v的访问标记为0）继续找其他路径，即允许曾经访问过的顶点出现在另外的路径中（原书图8.17）。\n第4步：函数FindAllPath在输出路径后置visited[u]=0，遍历完u的所有邻接点从函数返回前也置visited[u]=0恢复环境。",
       "src": "教材P266-267"
