       "solution": "第1步：图G的邻接表如图8.25（图G的邻接表不唯一）。各单链表为：0:1→2→3；1:0→4→5；2:0→3→5→6；3:0→2→7；4:1；5:1→2；6:2→7→8→9；7:3→6→10；8:6；9:6；10:7。\n第2步（DFS）：从顶点3出发深度优先遍历，过程为3→0→1→4，回溯；1→5→2→6→7→10，回溯；6→8，回溯；6→9。DFS访问序列 3 0 1 4 5 2 6 7 10 8 9；两顶点间连线构成深度优先生成树的边，树如图8.26(a)。\n第3步（BFS）：从顶点3出发广度优先遍历，按层：第0层{3}；第1层{0,2,7}；第2层{1,5,6,10}（0扩展出1，2扩展出5、6，7扩展出10）；第3层{4,8,9}（1扩展出4，6扩展出8、9）。BFS访问序列 3 0 2 7 1 5 6 10 4 8 9，树如图8.26(b)。",
