       "no": "例9.5",
       "stem": "输入关键字序列 (16,3,7,11,9,26,18,14,15)，给出构造一棵平衡二叉树的过程。",
       "solution": "按序逐个插入，每次插入后检查平衡因子并调整（原书图9.17）：\n(a) 插入 16：单结点 16，bf=0。\n(b) 插入 3：3 为 16 的左孩子；bf(16)=1，bf(3)=0。\n(c) 插入 7：7 为 3 的右孩子；bf(3)=-1，bf(16)=2，16 失衡，新结点在左孩子的右子树，属 LR。\n(d) LR 型调整：7 上升为子树根，3 为其左孩子，16 为其右孩子，三结点 bf 均为 0。\n(e) 插入 11：11 为 16 的左孩子；bf(16)=1，bf(7)=-1，其余为 0，树平衡。\n(f) 插入 9：9 为 11 的左孩子；bf(11)=1，bf(16)=2，16 失衡，新结点在左孩子的左子树，属 LL。\n(g) LL 型调整：11 上升，16 成为 11 的右孩子（11 原右子树为空）；调整后 7 为根，左孩子 3，右孩子 11，11 的左 9、右 16；bf(7)=-1，bf(11)=0。\n(h) 插入 26：26 为 16 的右孩子；bf(16)=-1，bf(11)=-1，bf(7)=-2，7 失衡，新结点在右孩子的右子树，属 RR。\n(i) RR 型调整：11 上升为根，7 成为 11 的左孩子，11 的原左子树 9 成为 7 的右子树；调整后根 11，左孩子 7（左 3、右 9），右孩子 16（右 26）；bf 均为 0（16 的 bf=-1）。\n(j) 插入 18：18 为 26 的左孩子；bf(26)=1，bf(16)=-2，16 失衡，新结点在右孩子的左子树，属 RL。\n(k) RL 型调整：18 上升，左孩子 16、右孩子 26，16 与 26 的原内侧子树均为空；调整后根 11，左 7（3、9），右 18（16、26），各结点 bf 均为 0。\n(l) 插入 14：14 为 16 的左孩子；bf(16)=1，bf(18)=1，bf(11)=-1，树平衡。\n(m) 插入 15：15 为 14 的右孩子；bf(14)=-1，bf(16)=2，16 失衡，新结点在左孩子的右子树，属 LR。\n(n) LR 型调整：15 上升，左孩子 14、右孩子 16；最终树逐结点描述为：根 11；左孩子 7（7 的左 3、右 9）；右孩子 18（18 的左 15、右 26）；15 的左 14、右 16。图9.17(n) 即最终结果。",
       "src": "教材P334-335"
